/* launcheck: no build step, no trackers, no remote frontend dependencies. */
(() => {
'use strict';
const state = { projects: [], project: null, meta: null, tab: 'overview', roleId: null, choices: {}, busy: false, workspace: null, connections: {}, channels: [], selectedChannels: [], members: [], slackDirectory: null, invitationLinks:[], employeeAnswers: {}, employee:null, employeeChannels:[], employeeInvite:null, builderMode:'both', builderCount:3, builderTeams:['Engineering','Marketing','Customer Support'], builderCustom:'What should your team do if the launch is delayed?' };
const tabs = [ ['overview','◈','Overview'], ['scenarios','◎','Team rehearsal'], ['readiness','▦','Readiness report'], ['sources','▤','Evidence sources'], ['integrations','⤧','Integrations'], ['team','♟','Team accounts'] ];
const roles = { 'Engineering': '⌘', 'Marketing':'✺', 'Customer Success':'◇', 'Support':'☏' };
const actLabels = {hold:'Hold release', pilot:'Restricted pilot', full:'Full launch'};
const $ = sel => document.querySelector(sel);
const esc = str => String(str ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message,error=false){const root=$('#toastRoot');const box=document.createElement('div');box.className='toast'+(error?' error':'');box.textContent=message;root.appendChild(box);setTimeout(()=>box.remove(),4100);}
async function api(path, opts={}) { const res=await fetch(path,opts);const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail || `Request failed (${res.status})`);return data; }
function post(path, body){return api(path,{method:'POST',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});}
function short(s,n=155){s=String(s||'').replace(/\s+/g,' ').trim();return s.length<=n?s:s.slice(0,n-1)+'…';}
function iconForSource(kind){return ({Email:'✉',Slack:'⌗',CSV:'▤',PDF:'▧',DOCX:'▧',Document:'▧',Text:'≡',JSON:'{}'})[kind]||'▧';}
function typeClass(kind){return kind==='Email'?'email':kind==='Slack'?'slack':kind==='CSV'?'csv':'';}
function num(n){return String(n||0).padStart(2,'0')}
function applyGate(mode){
  document.body.classList.add('onboarding');
  $('#projectBreadcrumb').textContent=mode==='setup'?'Your company':'Sign in';
  $('#primaryNav').innerHTML=''; $('#projectsNav').innerHTML='';
  const form = mode==='setup'?`<div class="eyebrow">GET STARTED · STEP 1</div><h1>Create your company workspace</h1><p>launcheck starts with your real company. Choose the services you want to connect; entering an email or workspace name does <b>not</b> grant access.</p>
  <form id="setupForm" class="setup-form">
  <div class="form-duo"><label class="setup-label">Company name<input id="setupCompany" class="text-field" required minlength="2" maxlength="90" placeholder="e.g. Mapleworks" /></label><label class="setup-label">Your name<input id="setupName" class="text-field" required minlength="2" maxlength="90" placeholder="e.g. Alex Morgan" /></label></div>
  <label class="setup-label">Your work email<input id="setupEmail" type="email" class="text-field" required placeholder="alex@mapleworks.com" /></label>
  <label class="setup-label">Create an owner password<input id="setupPassword" type="password" class="text-field" required minlength="10" autocomplete="new-password" placeholder="At least 10 characters" /></label>
  <h3 class="setup-section">Services you plan to connect</h3><p class="minor-copy">These are preferences, not sign-ins. You'll approve access through Slack or Google in the next step.</p>
  <div class="form-duo"><label class="setup-label">Slack workspace URL (optional)<input id="setupSlack" class="text-field" placeholder="mapleworks.slack.com" /></label><label class="setup-label">Gmail / Google Workspace address (optional)<input type="email" id="setupGmail" class="text-field" placeholder="alex@mapleworks.com" /></label></div>
  <div class="check-grid">${[['slack','⌗ Slack'],['gmail','✉ Gmail'],['drive','▧ Google Drive'],['teams','◉ Microsoft Teams'],['notion','▤ Notion'],['jira','◇ Jira']].map(([id,label])=>`<label class="check-card"><input type="checkbox" name="wanted" value="${id}" ${['slack','gmail'].includes(id)?'checked':''}/>${label}</label>`).join('')}</div>
  <button class="btn btn-wide" type="submit">Create workspace →</button>
  <p class="minor-copy">Hackathon prototype. Team members can be invited after setup. Only opt-in connections are used. Do not upload confidential data.</p>
  </form>`:`<div class="eyebrow">WELCOME BACK</div><h1>Sign in to launcheck</h1><p>Enter the credentials you created for this company workspace.</p><form id="loginForm" class="setup-form"><label class="setup-label">Work email<input id="loginEmail" class="text-field" type="email" required /></label><label class="setup-label">Password<input id="loginPassword" class="text-field" type="password" required /></label><button class="btn btn-wide">Sign in →</button><p class="minor-copy"><a href="/?team=1">Employee sign in instead</a></p></form>`;
  $('#appContent').innerHTML=`<div class="setup-frame"><div class="setup-aside"><div class="brand-mark large-brand">L<span>✓</span></div><div class="eyebrow">launcheck</div><h2>Before you launch,<br>get everyone aligned.</h2><p>Connect your tools, automatically assemble launch context, and check whether your teams would make compatible decisions.</p><div class="setup-mini">01 · Your company<br>02 · Authorize tools<br>03 · Run a launch check</div></div><section class="setup-card">${form}</section></div>`;
}
async function loadWorkspace(){const data=await api('/api/workspace');state.workspace=data.workspace;state.connections=data.connectors;state.selectedChannels=data.selected_channels.map(x=>x.channel_id);$('#companyLabel').textContent=data.workspace?.company||'Your company';$('#ownerAvatar').textContent=(data.workspace?.owner_name||'LC').split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();}
async function loadChannels(){if(!state.connections.slack?.connected){state.channels=[];return;}try{state.channels=await api('/api/connectors/slack/channels');}catch(e){state.channels=[];toast(e.message,true);}}
async function renderInvite(token){
 document.body.classList.add('onboarding');
 $('#projectBreadcrumb').textContent='Team invitation';
 try{const data=await api('/api/invite/'+encodeURIComponent(token));
  $('#appContent').innerHTML=`<div class="invite-wrap"><div class="card card-pad"><div class="eyebrow">PRIVATE TEAM READINESS CHECK</div><h1>${esc(data.project_name)} · ${esc(data.role)}</h1><p class="minor-copy">Respond independently. Your answer is shared with the project owner. Private company sources are not exposed.</p><h2>${esc(data.title)}</h2><div class="situation">${esc(data.situation)}</div><div class="question">${esc(data.question)}</div>${data.already_submitted?'<div class="account-tag">This invitation has already been used.</div>':`<form id="inviteForm"><input type="hidden" id="inviteToken" value="${esc(token)}"/><div class="choice-list">${data.options.map(o=>`<label class="choice"><input type="radio" name="inviteAction" value="${esc(o.action)}" required/>${esc(o.label)}</label>`).join('')}</div><label class="field-label">Your name<input class="text-field" id="inviteName" maxlength="80" required/></label><label class="field-label">Why? (optional)<textarea class="text-field" id="inviteRationale" maxlength="1400"></textarea></label><button class="btn" type="submit">Submit private answer →</button></form>`}</div></div>`;
 }catch(e){$('#appContent').innerHTML=`<div class="card card-pad"><h1>Invitation unavailable</h1><p>${esc(e.message)}</p></div>`;}
}
async function renderEmployeeJoin(token){
 document.body.classList.add('onboarding','employee-mode');$('#projectBreadcrumb').textContent='Join a company';
 try{state.employeeInvite=await api('/api/team/invite/'+encodeURIComponent(token));const i=state.employeeInvite;
 $('#appContent').innerHTML=`<div class="setup-frame"><div class="setup-aside"><div class="brand-mark large-brand">L<span>✓</span></div><h2>Join ${esc(i.company)}</h2><p>Your employer cannot see your mailbox by inviting you. After joining, you choose which tools and launches to share.</p></div><section class="setup-card"><div class="eyebrow">TEAM INVITATION</div><h1>Welcome, ${esc(i.role)}</h1><p>Invitation for <b>${esc(i.email)}</b>. Your connected accounts remain under your control.</p><form id="employeeJoinForm" class="setup-form"><input type="hidden" id="employeeToken" value="${esc(token)}"><label class="setup-label">Your name<input id="employeeName" class="text-field" required minlength="2" placeholder="Your name"></label><label class="setup-label">Create password<input id="employeePassword" class="text-field" type="password" minlength="10" required placeholder="At least 10 characters"></label><button class="btn btn-wide">Join company →</button></form></section></div>`;
 }catch(e){$('#appContent').innerHTML=`<div class="card card-pad"><h2>Invitation unavailable</h2><p>${esc(e.message)}</p></div>`;}
}
function employeeLoginScreen(){document.body.classList.add('onboarding','employee-mode');$('#projectBreadcrumb').textContent='Employee sign in';
 $('#primaryNav').innerHTML='';$('#projectsNav').innerHTML='';
 $('#appContent').innerHTML=`<div class="setup-frame"><div class="setup-aside"><div class="brand-mark large-brand">L<span>✓</span></div><h2>Your input matters.</h2><p>Connect only the accounts you want, and choose which launch decisions your project-related data can support.</p></div><section class="setup-card"><div class="eyebrow">EMPLOYEE ACCESS</div><h1>Sign in to launcheck</h1><form class="setup-form" id="employeeLoginForm"><label class="setup-label">Work email<input type="email" id="employeeEmail" class="text-field" required></label><label class="setup-label">Password<input id="employeeLoginPassword" class="text-field" type="password" required></label><button class="btn btn-wide">Sign in →</button><p class="minor-copy"><a href="/">Company owner sign-in</a></p></form></section></div>`;
}
async function initEmployee(){try{document.body.classList.add('employee-mode');state.employee=await api('/api/team/me');document.body.classList.remove('onboarding');$('#companyLabel').textContent='EMPLOYEE PORTAL';$('#ownerAvatar').textContent=state.employee.employee.name.slice(0,2).toUpperCase();$('#projectBreadcrumb').textContent=state.employee.employee.name;$('#modeBadge').textContent='● Opt-in sharing';$('#primaryNav').innerHTML='';$('#projectsNav').innerHTML='';await loadEmployeeChannels();renderEmployee();}catch(e){employeeLoginScreen();}}
async function loadEmployeeChannels(){const e=state.employee;if(!e?.connectors.slack?.connected){state.employeeChannels=[];return;}try{state.employeeChannels=await api('/api/team/connectors/slack/channels');}catch(error){state.employeeChannels=[];}}
function renderEmployee(){const e=state.employee;if(!e){employeeLoginScreen();return;}document.body.classList.remove('onboarding');const me=e.employee;
 $('#appContent').innerHTML=`${titleBlock('TEAM MEMBER · '+esc(me.role),'Hello, '+esc(me.name),'You decide what project-related information to share with your company. Connecting an account alone does not share its messages.',`<button class="btn btn-outline" data-action="employee-logout">Sign out</button>`)}
 <div class="card card-pad"><h2>My assigned launch questions</h2><p>Your boss will see your answer in the readiness report. You can answer here without sharing your private messages or connecting Slack/Gmail.</p>
 ${e.assignments?.length?e.assignments.map(a=>`<div class="check-card" style="margin-top:12px;display:block"><span class="eyebrow">${esc(a.project_name)} · ${esc(a.role)}</span><h3>${esc(a.title)}</h3><p>${esc(a.situation)}</p><p><b>${esc(a.question)}</b></p>${a.response_id?`<p class="account-tag">✓ Answer recorded: ${esc(actLabels[a.response_action]|| (a.response_action==='text'?'Written response submitted':a.response_action))}</p>`:`<form data-employee-scenario="${esc(a.id)}">${a.question_type==='text'?`<label class="field-label">Your answer<textarea class="text-field" name="reason" maxlength="1400" required placeholder="Describe what your team would do…"></textarea></label>`:`<div class="choice-list">${a.options.map(o=>`<label class="choice"><input type="radio" name="answer-${esc(a.id)}" value="${esc(o.action)}" required>${esc(o.label)}</label>`).join('')}</div><label class="field-label">Why? (optional)<textarea class="text-field" name="reason" maxlength="1400"></textarea></label>`}<button class="btn btn-small" type="submit">Submit my response →</button></form>`}</div>`).join(''):'<p>No questions assigned to your department yet. Ask your boss to generate scenarios for your role.</p>'}</div>
 <div class="card card-pad" style="margin-top:20px"><h2>1 · Connect your own accounts</h2><p>These connections belong to you, not the company owner. Gmail access is read-only for the authorized mailbox; Slack is limited to selected public channels you can access. Each tool asks for separate permission.</p>
 <div class="connection-grid">${[['gmail','✉','Gmail'],['slack','⌗','Slack']].map(([id,icon,title])=>{const c=e.connectors[id];return `<div class="card card-pad"><div class="connection-title"><span class="connection-glyph">${icon}</span><h3>${title}</h3><span class="badge ${c.connected?'':'badge-warning'}">${c.connected?'Connected':'Not connected'}</span></div>${c.connected?`<p class="account-tag">✓ ${esc(c.label)}</p><button class="btn btn-outline btn-small" data-action="employee-disconnect" data-provider="${id}">Disconnect & delete imported context</button>`:`<button class="btn btn-small" data-action="employee-connect" data-provider="${id}" ${c.available?'':'disabled'}>Connect my ${title} →</button>${c.available?'':'<p class="minor-copy">Owner must configure OAuth credentials first.</p>'}`}</div>`}).join('')}</div>
 ${e.connectors.slack.connected?`<div style="margin-top:20px"><h3>Which Slack channels may be searched?</h3><p>Choose up to three public channels from your own account. DMs and private channels are excluded.</p>${state.employeeChannels.length?`<form id="employeeChannelsForm"><div class="check-grid">${state.employeeChannels.map(ch=>`<label class="check-card"><input type="checkbox" name="employeeChannel" value="${esc(ch.id)}" ${ch.selected?'checked':''}>#${esc(ch.name)}</label>`).join('')}</div><button class="btn btn-small">Save channels</button></form>`:'<p>No accessible public Slack channels available yet.</p>'}<button class="btn btn-outline btn-small" data-action="employee-refresh-channels">Refresh channels</button></div>`:''}</div>
 <div class="card card-pad" style="margin-top:20px"><h2>2 · Choose which launch checks to help with</h2><p><b>Explicit opt-in:</b> Only launches you approve will use relevant excerpts from your connected accounts. The company owner can view the imported excerpts; they may be sent to an AI provider when scenarios are generated. You can revoke and delete your imported content at any time.</p>${e.projects.length?`<div class="check-grid">${e.projects.map(p=>`<div class="check-card"><h3>${esc(p.name)}</h3><p>${esc(short(p.decision,160))}</p><button class="btn ${p.shared?'btn-outline':'btn-soft'} btn-small" data-action="employee-share" data-project-id="${esc(p.id)}" data-shared="${p.shared?'1':'0'}">${p.shared?'✓ Sharing enabled · Revoke':'Opt in to this launch'}</button></div>`).join('')}</div>`:'<p>No active launch checks yet. Ask your owner to create one.</p>'}</div>
 <p class="minor-copy" style="margin-top:12px">This is a hackathon prototype: private links are not email-verified, stored excerpts are not encrypted, and access has not been production security-reviewed. Use fictional or approved test data only.</p>`;
}
async function init(){try{
  const route=new URL(location.href);
  if(route.searchParams.has('join')){await renderEmployeeJoin(route.searchParams.get('join'));return;}
  if(route.searchParams.has('team')){await initEmployee();return;}
  const inviteToken=route.searchParams.get('invite');
  if(inviteToken){await renderInvite(inviteToken);return;}
  state.meta=await api('/api/meta');const status=await api('/api/setup-status');
  if(status.setup_required){applyGate('setup');return;}
  if(!status.signed_in){applyGate('login');return;}
  document.body.classList.remove('onboarding');
  await loadWorkspace();state.projects=await api('/api/projects');
  const url=new URL(location.href);if(url.searchParams.has('connected')){state.tab='integrations';await loadChannels();history.replaceState({},'',location.pathname);toast('Connected! Visit Team accounts to invite your coworkers from Slack.');}
  const desired=url.searchParams.get('project');const project=state.projects.find(p=>p.id===desired)||state.projects[0];
  if(project){state.project=await api(`/api/projects/${project.id}`);const role=url.searchParams.get('role');if(role){state.tab='scenarios';state.roleId=state.project.scenarios.find(s=>s.role===role)?.id||null;}}
  if(state.tab==='team')state.members=await api('/api/team/members');
  render();
 }catch(e){$('#appContent').innerHTML=`<div class="card card-pad"><h2>Couldn't start launcheck</h2><p>${esc(e.message)}</p><p>Start the server with <code>uvicorn app:app --reload</code>.</p></div>`;}}

function urlFor(project){const u=new URL(location.href);u.searchParams.set('project',project.id);u.searchParams.delete('role');history.replaceState({},'',u.toString());}
function updateProject(project){state.project=project;state.roleId=state.project.scenarios.find(s=>s.id===state.roleId)?.id || state.project.scenarios[0]?.id||null;urlFor(project);render();}
function render(){const p=state.project;$('#projectBreadcrumb').textContent=p?p.name:state.workspace?.company||'Workspace';$('#modeBadge').textContent=state.meta?.ai_enabled?'● AI ready':'● AI key not configured';
$('#primaryNav').innerHTML=tabs.map(([id,icon,label])=>`<button data-tab="${id}" class="nav-item ${state.tab===id?'active':''}"><span class="nav-icon">${icon}</span><span class="nav-text">${label}</span>${id==='readiness'&&p?.report?.conflicts?.length?`<span class="nav-count">${p.report.conflicts.length}</span>`:''}</button>`).join('');
$('#projectsNav').innerHTML=state.projects.map(o=>`<button data-project="${o.id}" class="project-item ${o.id===p?.id?'active':''}"><span class="project-dot"></span><span class="project-text">${esc(o.name)}</span></button>`).join('');
$('#appContent').innerHTML=state.tab==='team'?teamOwner():state.tab==='integrations'?integrations():!p?noProjectPage(state.tab):state.tab==='overview'?overview(p):state.tab==='scenarios'?scenarios(p):state.tab==='readiness'?readiness(p):sources(p); }
function noProjectPage(tab){
 if(tab==='scenarios')return `${titleBlock('STEP 02 · TEAM REHEARSAL','Create a launch check to ask your teams questions.','This is where employees will answer separate what-if questions about your launch.')}
 <div class="card empty-panel"><span class="empty-state-badge">◎</span><h3>No launch project selected</h3><p>Start by creating a launch check. After you collect Slack messages or upload documents, generate team-specific questions here.</p><button class="btn" data-action="open-create">+ Create launch check</button></div>`;
 if(tab==='readiness')return `${titleBlock('STEP 03 · READINESS REPORT','Results will appear after the team answers.','This page is for the boss to review conflicting plans—not for employees to take the test.')}
 <div class="card empty-panel"><span class="empty-state-badge">▦</span><h3>No launch results yet</h3><p>Create a launch check, generate questions under Team rehearsal, and collect responses to see an alignment report.</p><button class="btn" data-action="open-create">+ Create launch check</button></div>`;
 if(tab==='sources')return `${titleBlock('STEP 01 · EVIDENCE SOURCES','Create a launch check to gather context.','Choose a launch first. launcheck will search your authorized sources and let you review the imported evidence.')}
 <div class="card empty-panel"><span class="empty-state-badge">▤</span><h3>No active launch project</h3><p>Create a check to find relevant Slack and Gmail messages or upload your own context.</p><button class="btn" data-action="open-create">+ Create launch check</button></div>`;
 return welcome();
}
function welcome(){return `${titleBlock('YOUR WORKSPACE','Welcome to '+esc(state.workspace?.company||'launcheck'),'Connect your own information sources, then start a readiness check.')}
<div class="welcome-grid"><div class="card card-pad"><span class="eyebrow">STEP 1 · CONNECT</span><h2>Bring in your real context</h2><p>Authorize Slack and Gmail using official sign-in. Select only the Slack channels you want searched.</p><button class="btn" data-tab="integrations">Manage integrations →</button></div><div class="card card-pad"><span class="eyebrow">STEP 2 · DECIDE</span><h2>What are you about to launch?</h2><p>Once you create a launch check, launcheck searches your authorized sources for recent relevant discussions.</p><button class="btn btn-outline" data-action="open-create">+ Start a launch check</button></div></div><div class="card card-pad" style="margin-top:22px"><h3>Need a fictional judging demo?</h3><p>You can add an explicitly labeled example project, but none is created automatically.</p><button class="btn btn-soft" data-action="create-demo">Create fictional demo data</button></div>`;}
function integrations(){const c=state.connections||{};const ws=state.workspace||{};
return `${titleBlock('WORKSPACE SETUP','Connect '+esc(ws.company||'your company')+' tools','Authorize specific accounts. launcheck searches recent messages relevant to the launch decision, then stores only the imported results for review.')}
<div class="connection-grid">${[['slack','⌗','Slack','Recent messages in up to three channels you explicitly select. Invite the app to those channels first.'],['gmail','✉','Gmail','Up to 12 matching emails from this owner’s authorized mailbox in the past 30 days.']].map(([id,ico,title,description])=>`<article class="card card-pad"><div class="connection-title"><span class="connection-glyph">${ico}</span><h3>${title}</h3><span class="badge ${c[id]?.connected?'':'badge-warning'}">${c[id]?.connected?'Connected':'Not connected'}</span></div><p>${description}</p>${c[id]?.connected?`<div class="account-tag">✓ ${esc(c[id].label)}</div><button class="btn btn-outline btn-small" data-action="disconnect" data-provider="${id}">Disconnect & delete imported context</button>`:`<button class="btn btn-small" data-action="connect" data-provider="${id}" ${c[id]?.available?'':'disabled'}>Connect ${title} with OAuth →</button>${c[id]?.available?'':'<p class="minor-copy">OAuth app credentials are not configured on the server. See README.</p>'}`}</article>`).join('')}</div>
${c.slack?.connected?`<div class="card card-pad" style="margin-top:18px"><div class="compact-head"><h3>Choose Slack channels to search</h3><span class="badge badge-purple">Up to 3 channels</span></div><p class="minor-copy">Only channels that the connected Slack bot has joined are listed. The app cannot access every employee's private conversations.</p>${state.channels.length?`<form id="channelsForm"><div class="check-grid">${state.channels.map(ch=>`<label class="check-card"><input type="checkbox" name="channel" value="${esc(ch.id)}" ${state.selectedChannels.includes(ch.id)?'checked':''} />#${esc(ch.name)}</label>`).join('')}</div><button class="btn btn-small">Save selected channels</button></form>`:'<p class="minor-copy">No joined channels found. Invite the connected Slack bot to a relevant public Slack channel, then click Refresh.</p>'}<button class="btn btn-outline btn-small" data-action="refresh-channels">Refresh channels</button></div>`:''}
<div class="card card-pad" style="margin-top:18px"><h3>Recommended next integrations</h3><div class="roadmap-grid">${[['Google Drive','Launch plans, PRDs, checklists'],['Microsoft Teams + Outlook','Organizations using Microsoft 365'],['Notion / Confluence','Requirements and decisions'],['Jira / Linear','Engineering blockers and release gates'],['GitHub','Merged code, deployment readiness'],['Google Calendar','Key meetings and deadline changes'],['Salesforce / HubSpot','Customer commitments'],['Zendesk / Intercom','Support readiness and reported issues']].map(([a,b])=>`<div class="roadmap"><b>${a}</b><small>${b}</small><span>Planned</span></div>`).join('')}</div><p class="minor-copy">These are roadmap recommendations, not working connections. You can upload documents from these systems today.</p></div>
<div class="card card-pad" style="margin-top:18px"><h3>Privacy & scope</h3><p class="minor-copy">OAuth sign-in is required. Owner connections and individually authorized employee connections are independent. An employee's context is used only after they explicitly opt in to a launch. Selected, relevant email and channel excerpts are visible to the owner; OpenAI receives excerpts only when the owner explicitly generates scenarios. Do not use confidential company data in this local hackathon prototype.</p><button class="btn btn-outline btn-small" data-action="logout">Sign out</button></div>`;}
function teamOwner(){
 const members=state.members||[];
 return `${titleBlock('WORKSPACE · PEOPLE','Invite your teams','Find teammates in Slack and create private links to send yourself. No email service or domain required. Once employees join, their assigned questions appear in their own dashboard.')}
 <div class="card card-pad"><h2>Find teammates in Slack</h2><p>Load members of your connected Slack workspace, select the people you want to invite, and choose a department for each. <b>No invitations are emailed.</b> Slack directory access requires <code>users:read</code> and <code>users:read.email</code>.</p>
 <button class="btn btn-small" data-action="slack-people" ${state.connections.slack?.connected?'':'disabled'}>Find teammates in Slack →</button>
 ${state.slackDirectory?`<div style="margin-top:18px"><p>${state.slackDirectory.members.length} eligible Slack members found. Choose who should receive a private invitation link.</p><form id="slackInviteForm"><div class="check-grid">${state.slackDirectory.members.map((m,i)=>`<div class="check-card" style="display:block"><label><input type="checkbox" name="slackInviteSelect" value="${i}" ${m.already_joined?'disabled':''}/> <b>${esc(m.name)}</b></label><p>${esc(m.email)}</p><p class="minor-copy">${m.already_joined?'Already joined':'Ready for invitation'}</p><label class="setup-label" style="display:block;margin-top:10px">Department <select class="text-field" data-slack-role="${i}" ${m.already_joined?'disabled':''}><option>Engineering</option><option>Marketing</option><option>Support</option><option>Customer Success</option><option>Product</option></select></label></div>`).join('')}</div><button class="btn" type="submit">Create private invitation links →</button><p class="minor-copy">You will copy each generated link and send it to your teammates yourself. Generating a new link for a person invalidates any previous unredeemed link for that person.</p></form></div>`:''}
 ${state.invitationLinks.length?`<div class="card card-pad" style="margin-top:16px"><h3>Your invitation links — share privately</h3><p class="minor-copy">No emails have been sent. Copy these links now; they are shown only in this browser session and expire in 72 hours. Anyone with a link could claim that account in this prototype.</p>${state.invitationLinks.map((m,i)=>`<div style="margin:12px 0;overflow-wrap:anywhere"><b>${esc(m.email)} · ${esc(m.role)}</b><div class="minor-copy">${esc(m.url)}</div><button class="btn btn-outline btn-small" data-action="copy-slack-link" data-link-index="${i}">Copy invitation link</button></div>`).join('')}</div>`:''}
 </div>
 <div class="card card-pad" style="margin-top:18px"><h2>Invite someone not in the Slack directory</h2><p>Create one private invitation link to copy and send manually. Links expire after 72 hours.</p>
 <form id="teamInviteForm" class="setup-form"><div class="form-duo"><label class="setup-label">Employee work email<input id="newEmployeeEmail" type="email" class="text-field" required placeholder="engineer@yourcompany.com"></label><label class="setup-label">Department / role<input id="newEmployeeRole" class="text-field" required placeholder="Engineering" maxlength="80"></label></div><button class="btn">Create private invitation link →</button></form></div>
 <div class="card card-pad" style="margin-top:18px"><h3>Joined employees (${members.length})</h3>${members.length?`<div class="check-grid">${members.map(m=>`<div class="check-card"><strong>${esc(m.name)} · ${esc(m.role)}</strong><p>${esc(m.email)}</p><small>${m.connected_count} tools connected · ${m.shared_count} launches opted into</small></div>`).join('')}</div>`:'<p>No employees have joined yet. Invite your first team member above.</p>'}</div>
 <div class="card card-pad" style="margin-top:18px"><h3>Important about access</h3><p class="minor-copy">Invitation links do not give permission to read employee Gmail or Slack. Employees connect and opt in separately. Use fictional data and throwaway passwords for this local HTTP prototype; invite links do not verify email ownership.</p></div>`;
}
function titleBlock(label,title,description,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${description}</p></div>${buttons?`<div class="heading-actions">${buttons}</div>`:''}</div>`;}
function overview(p){const r=p.report;const sources=p.sources.slice(0,4);return `
${titleBlock('WORKSPACE OVERVIEW','Every team on the same page.','Making an impactful company decision? Prevent disasters before they happen with launcheck.',`<button class="btn btn-outline" data-tab="sources">⊕ View context</button>`)}
<div class="grid-hero"><section class="hero-main"><div class="hero-corner"></div><div class="eyebrow">Before you launch: Team rehearsal</div><h2>Don’t just say you’re ready.<br><em>Prove you’re on the same page.</em></h2><p>Turn a single launch decision into role-specific scenarios, then see whether your teams would actually make compatible decisions.</p><div class="button-row"><button class="btn" data-tab="scenarios">Start team rehearsal <span class="btn-icon">→</span></button>${p.is_demo?`<button class="btn btn-soft" data-action="simulate">▶ Simulate responses</button>`:''}</div></section>
<section class="card decision-card"><div class="decision-top"><span class="card-kicker">CURRENT DECISION</span><span class="badge badge-purple">Decision #01</span></div><p class="decision-text">“${esc(p.decision)}”</p><span class="small-label">Linked sources</span><div class="source-stacks">${['✉ Emails','⌗ Chats','▧ Documents'].map(t=>`<span class="source-chip">${t}</span>`).join('')}</div><div class="divider"></div><div class="inline-status"><span class="status-point ${r.stance==='aligned'?'good':''}"></span>${r.responses_count===0?'Awaiting team decisions':esc(r.headline)}</div></section></div>
<div class="metric-grid"><article class="card metric-card"><div><div class="metric-label">Team responses</div><div class="metric-value">${r.responses_count}<span style="font-size:16px;color:#a4acc0;font-weight:500"> / ${r.total_roles}</span></div><div class="metric-foot">Independent perspectives</div></div><div class="metric-icon">♧</div></article><article class="card metric-card"><div><div class="metric-label">Cross-team conflicts</div><div class="metric-value">${num(r.conflicts.length)}</div><div class="metric-foot">Incompatible actions identified</div></div><div class="metric-icon">⚡</div></article><article class="card metric-card"><div><div class="metric-label">Evidence sources</div><div class="metric-value">${num(p.sources.length)}</div><div class="metric-foot">Context across your workspace</div></div><div class="metric-icon">▤</div></article></div>
<div class="section-head"><h3>How launcheck works</h3><span>Three steps to actionable alignment</span></div><div class="steps-grid"><article class="card step-card"><span class="step-num">STEP 01</span><span class="step-icon">▧</span><h4>Connect your context</h4><p>Combine relevant project emails, Slack exports and documents in a single, attributable evidence model.</p></article><article class="card step-card"><span class="step-num">STEP 02</span><span class="step-icon">♧</span><h4>Rehearse team decisions</h4><p>Each role answers its own real-world what-if scenario based on the same implementation decision.</p></article><article class="card step-card"><span class="step-num">STEP 03</span><span class="step-icon">◉</span><h4>Resolve hidden gaps</h4><p>Compare intended actions, pinpoint conflicting release plans and draft a clarification for everyone.</p></article></div>
<div class="bottom-grid single"><article class="card card-pad"><div class="compact-head"><h3>Connected evidence</h3><button class="text-link" data-tab="sources">View all ${p.sources.length} →</button></div>${sources.map(s=>`<div class="mini-source"><span class="file-icon ${typeClass(s.kind)}">${iconForSource(s.kind)}</span><div><div class="mini-file-name">${esc(s.filename)}</div><div class="mini-file-kind">${esc(s.kind)} · Context imported</div></div><span class="source-arrow">↗</span></div>`).join('')||'<p class="minor-copy">Add documents to get started.</p>'}</article></div>`;}
function selectedOption(s){return state.choices[s.id]||s.response?.action||'';}
function questionBuilder(p){
 const drafts=p.scenarios.filter(q=>q.status==='draft');
 const departmentChoices=['Engineering','Marketing','Customer Support','Product Launch Team','Support','Customer Success','Product'];
 return `<section class="card card-pad question-builder"><div class="compact-head"><div><div class="eyebrow">CEO QUESTION BUILDER</div><h2>Design your team readiness check</h2></div><span class="badge badge-purple">${drafts.length} unpublished draft(s)</span></div>
 <p>Generate multiple AI questions per team, add your own written questions, review and edit everything, then publish them to employees' dashboards. Your current published answers remain intact.</p>
 <form id="questionBuilderForm" class="qb-controls">
 <div class="form-duo"><label class="setup-label">Question mode<select id="qbMode" class="text-field"><option value="both" ${state.builderMode==='both'?'selected':''}>Both AI + CEO questions</option><option value="ai" ${state.builderMode==='ai'?'selected':''}>AI only</option><option value="manual" ${state.builderMode==='manual'?'selected':''}>CEO questions only</option></select></label><label class="setup-label">AI questions per department<input type="number" id="qbCount" class="text-field" min="1" max="10" value="${state.builderCount}" ${state.builderMode==='manual'?'disabled':''}/></label></div>
 <label class="setup-label">Assign to departments</label><div class="qb-departments">${departmentChoices.filter((x,i,a)=>a.indexOf(x)===i).map(t=>`<label><input type="checkbox" name="qbDepartment" value="${esc(t)}" ${state.builderTeams.includes(t)?'checked':''}> ${esc(t)}</label>`).join('')}</div>
 <label class="setup-label">Your custom written-response question<textarea id="qbCustom" class="text-field" rows="2" maxlength="1200" ${state.builderMode==='ai'?'disabled':''}>${esc(state.builderCustom)}</textarea></label>
 <div class="button-row"><button class="btn" type="submit">${state.builderMode==='manual'?'Create custom drafts':'Generate draft questions'} →</button><button type="button" class="btn btn-outline" data-action="add-manual-question">+ Add another custom question</button></div><p class="minor-copy">Drafts are private to the CEO until published. AI requires imported evidence and an OpenAI API key; manual questions do not.</p></form>
 ${drafts.length?`<div class="qb-review"><div class="compact-head"><h3>Review and edit drafts</h3><button class="btn btn-small" data-action="publish-drafts">Publish all ${drafts.length} draft questions →</button></div><p class="minor-copy">Publish when you're satisfied. Assigned employees will see published questions on their next dashboard refresh.</p>
 ${drafts.map((q,i)=>`<form class="qb-draft" data-edit-question="${esc(q.id)}"><div class="qb-draft-heading"><strong>Draft ${i+1} · ${q.question_type==='text'?'Written response':'Multiple choice'}</strong><span class="badge">${esc(q.role)}</span></div>
 <div class="form-duo"><label class="setup-label">Assign department<select name="role" class="text-field">${departmentChoices.filter((x,i,a)=>a.indexOf(x)===i || x===q.role).concat(departmentChoices.includes(q.role)?[]:[q.role]).map(t=>`<option ${q.role===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="setup-label">Title<input class="text-field" name="title" maxlength="160" required value="${esc(q.title)}"/></label></div>
 <label class="setup-label">Situation (context)<textarea class="text-field" name="situation" maxlength="1200" rows="2">${esc(q.situation)}</textarea></label><label class="setup-label">Question<textarea class="text-field" name="question" maxlength="1200" minlength="5" required rows="2">${esc(q.question)}</textarea></label>
 ${q.question_type==='multiple_choice'?`<div class="qb-options"><label class="setup-label">Hold option<input class="text-field" name="option-hold" required value="${esc(q.options.find(x=>x.action==='hold')?.label||'Hold the launch')}"/></label><label class="setup-label">Pilot option<input class="text-field" name="option-pilot" required value="${esc(q.options.find(x=>x.action==='pilot')?.label||'Limited pilot')}"/></label><label class="setup-label">Full launch option<input class="text-field" name="option-full" required value="${esc(q.options.find(x=>x.action==='full')?.label||'Full launch')}"/></label></div>`:''}
 <div class="button-row"><button class="btn btn-small" type="submit">Save edits</button><button type="button" class="btn btn-outline btn-small" data-action="publish-one" data-id="${esc(q.id)}">Publish question</button><button type="button" class="btn btn-outline btn-small" data-action="delete-draft" data-id="${esc(q.id)}">Delete draft</button></div></form>`).join('')}</div>`:''}
 </section>`;
}
function addManualQuestionModal(){const p=state.project;if(!p)return;
 renderModal(`<div class="eyebrow">NEW CEO QUESTION</div><h2>Add a written-response question</h2><p>Assign it to a department, save as draft, and publish when ready.</p><form id="manualQuestionForm" class="setup-form"><label class="setup-label">Department<select class="text-field" id="manualDepartment">${['Engineering','Marketing','Customer Support','Product Launch Team','Support','Customer Success'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="setup-label">Title<input id="manualTitle" class="text-field" required value="CEO follow-up question"/></label><label class="setup-label">Question<textarea id="manualText" class="text-field" required minlength="5" maxlength="1200" rows="3" placeholder="What should your team do if the launch is delayed?"></textarea></label><div class="modal-footer"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn">Save draft</button></div></form>`);
}
function scenarios(p){const list=p.scenarios.filter(s=>s.status==='published');const selected=list.find(s=>s.id===state.roleId)||list[0];if(selected)state.roleId=selected.id;
return `${titleBlock('STEP 02 · TEAM REHEARSAL','Test the team, not their memory.','Each stakeholder gets a role-specific operational scenario. Their answers reveal whether the same decision leads to different actions.',`<button class="btn btn-outline" data-tab="readiness">View readiness report →</button>`)}
${questionBuilder(p)}
${list.length?`<div class="rehearsal-layout"><aside class="card roles-list">${list.map(s=>`<button class="role-select ${s.id===state.roleId?'active':''}" data-roleid="${s.id}"><span class="role-avatar ${s.role.toLowerCase().replace(/\s/g,'-').includes('marketing')?'marketing':s.role.toLowerCase().includes('support')?'support':s.role.toLowerCase().includes('customer')?'customer':''}">${roles[s.role]||'◇'}</span><span style="min-width:0"><span class="role-name">${esc(s.role)} · ${esc(short(s.title,28))}</span><span class="role-subtitle" style="display:block">${s.response?'Response submitted':'Awaiting response'}</span></span><span class="role-state ${s.response?'done':''}">${s.response?'✓':'→'}</span></button>`).join('')}</aside><article class="card survey-card"><div class="survey-tag">◈ DECISION SIMULATION · ${esc(selected.role)}</div><h2>${esc(selected.title)}</h2><div class="situation">“${esc(selected.situation)}”</div><div class="question">${esc(selected.question)}</div>${selected.question_type==='text'?'<div class="account-tag">Written response · employees answer in their own dashboards</div>':`<div class="choice-list">${selected.options.map((o,i)=>`<label class="choice ${selectedOption(selected)===o.action?'selected':''}" data-choice="${o.action}" data-scenario="${selected.id}"><span class="choice-radio"></span><span><strong style="font-weight:750">${esc(o.label)}</strong></span></label>`).join('')}</div>`}<label class="field-label" for="participantName">Your name / representative</label><input id="participantName" class="text-field" placeholder="e.g. Priya · Engineering" value="${esc(selected.response?.participant||'')}" maxlength="80"/><label class="field-label" for="rationale">${selected.question_type==='text'?'Your written answer':'Reasoning'} <span style="font-weight:500">${selected.question_type==='text'?'(required)':'(optional)'}</span></label><textarea class="text-field" id="rationale" placeholder="What makes this the right response?" maxlength="1400">${esc(selected.response?.rationale||'')}</textarea><div class="survey-footer"><small>Responses can be edited. Each team should answer independently.</small><button class="btn" data-action="save-response" data-scenario="${selected.id}" ${selected.question_type==='text'?'':!selectedOption(selected)?'disabled':''}>${selected.response?'Update response':'Submit response'} →</button></div><div class="evidence-list"><span class="small-label" style="align-self:center">Grounded in</span>${selected.source_ids.map(id=>{const src=p.sources.find(x=>x.id===id);return src?`<button data-source="${id}" class="evidence-pill">▧ ${esc(src.filename)}</button>`:''}).join('')}</div><div class="help-strip">ℹ ${p.is_demo?'This preloaded fictional scenario is curated for demonstration.':'AI-generated scenarios are working assumptions; verify them against the referenced sources.'}</div></article></div>`:`<div class="card empty-panel"><span class="empty-state-badge">✧</span><h3>No scenarios yet</h3><p>Add relevant sources, then generate role-specific team questions using a configured OpenAI API key. The seeded demo contains ready-to-try scenarios.</p><div class="button-row" style="justify-content:center"><button class="btn btn-outline" data-tab="sources">Add sources</button><button class="btn" data-action="scroll-builder">✦ Use question builder</button></div></div>`}
<div class="section-head"><h3>Need a fast demo?</h3><span>Use synthetic, fictional team responses</span></div><div class="button-row">${p.is_demo?`<button class="btn btn-soft" data-action="simulate">▶ Fill in fictional team responses</button>`:''}<button class="btn btn-outline" data-action="scroll-builder">✦ Configure question builder</button>${list.length?`<button class="btn btn-outline" data-action="share-role">↗ Copy private ${esc(selected?.role||'team')} invite</button>`:''}</div>`;}
function readiness(p){const r=p.report;const pct=r.total_roles?Math.round(r.responses_count/r.total_roles*100):0;
 if(!p.scenarios.some(s=>s.status==='published'))return `${titleBlock('STEP 03 · READINESS REPORT','No questions to compare yet.','Generate role-specific questions and let employees submit their answers before reviewing the alignment report.')}
 <div class="card empty-panel"><span class="empty-state-badge">▦</span><h3>Start with Team rehearsal</h3><p>First, generate questions from your launch context. Then have each department answer independently. This page will show their plans and highlight incompatible decisions.</p><button class="btn" data-tab="scenarios">Go to Team rehearsal →</button></div>`;
 if(r.responses_count===0)return `${titleBlock('STEP 03 · READINESS REPORT','Waiting for team responses.','The questions are ready, but nobody has answered them yet. This page summarizes answers—it does not collect them.')}
 <div class="card card-pad"><div class="eyebrow">TEAM PARTICIPATION</div><h2>0 of ${r.total_roles} answers received</h2><p>No conflicts can be confirmed before your teams submit their choices.</p><button class="btn" data-tab="scenarios">Go to Team rehearsal →</button></div>`;
 return `${titleBlock('STEP 03 · ALIGNMENT REPORT','Find the gaps before go-live.','Responses are compared at the action level. Disagreement is surfaced with a suggested clarification and the source evidence that matters.',`<button class="btn btn-outline" data-action="clear-responses">↺ Reset answers</button><button class="btn" data-action="copy-message">▣ Copy action summary</button>`)}
<div class="readiness-banner ${r.stance==='attention'?'alert':r.stance==='aligned'?'aligned':''}"><div class="ready-left"><span class="ready-icon">${r.stance==='attention'?'⚠':r.stance==='aligned'?'✓':'◎'}</span><div><div class="eyebrow">ALIGNMENT STATUS</div><h2>${esc(r.headline)}</h2><p>${r.conflicts.length} conflicting release postures · ${r.unsupported.length} responses warrant evidence review</p></div></div><div class="progress-side"><div class="progress-heading"><span>Team participation</span><b>${pct}% complete</b></div><div class="progress"><div class="progress-inner" style="width:${pct}%"></div></div><div class="minor-copy">${r.responses_count} of ${r.total_roles} scenarios answered</div></div></div>
<div class="readiness-columns"><section class="card table-card"><div class="compact-head"><h3>What each team would do</h3><span class="small-label">SHARED RELEASE DECISION</span></div><table><thead><tr><th>TEAM</th><th>ACTION SELECTED</th><th>STATUS</th></tr></thead><tbody>${p.scenarios.filter(s=>s.status==='published').map(s=>`<tr><td><span class="role-cell"><span class="role-small">${roles[s.role]||'◇'}</span>${esc(s.role)}</span></td><td><span class="action-pill ${s.response?.action||'unknown'}">${esc(s.response?(s.response.action==='text'?'Written response':actLabels[s.response.action]):'Awaiting response')}</span></td><td><span style="color:${s.response?'#19a87c':'#9fa7b6'};font-weight:650">${s.response?'✓ Submitted':'○ Pending'}</span></td></tr>`).join('')}</tbody></table><p class="minor-copy">Responses represent what participants selected in this simulation; they do not prove actual launch readiness.</p></section>
<section class="card risk-card"><div class="compact-head"><h3>Cross-team conflicts</h3><span class="badge ${r.conflicts.length?'badge-danger':''}">${r.conflicts.length} identified</span></div>${r.conflicts.length?r.conflicts.map(c=>`<div class="risk-item"><h4>⚡ ${esc(c.title)}</h4><p>${esc(c.description)}</p><div class="risk-meta"><span>${c.severity==='high'?'HIGH IMPACT':'REVIEW'}</span><span>${c.roles.length} teams</span></div></div>`).join(''):`<div class="empty-panel" style="padding:35px 8px"><div class="empty-emoji">${r.responses_count?'◉':'◇'}</div><h3>${r.responses_count?'No incompatible actions yet':'Waiting for team input'}</h3><p>${r.responses_count?'The submitted actions match so far. Check the evidence review items below.':'Complete at least two team responses to reveal cross-functional differences.'}</p></div>`}</section></div>
${r.written_answers?.length?`<section class="card card-pad" style="margin:18px 0"><h3>Written answers from employees</h3>${r.written_answers.map(a=>`<div class="qb-written"><strong>${esc(a.role)} · ${esc(a.participant)}</strong><p><b>${esc(a.question)}</b></p><p>${esc(a.answer)}</p></div>`).join('')}</section>`:''}
<div class="next-actions"><article class="card card-pad"><div class="compact-head"><h3>Recommended next step</h3><span class="badge badge-purple">Actionable output</span></div><div class="message-box">${esc(r.suggested_message)}</div><button class="btn btn-outline btn-small" data-action="copy-message">▣ Copy clarification message</button><p class="minor-copy">Draft for human approval. No emails or Slack messages are sent automatically.</p></article><article class="card card-pad"><div class="compact-head"><h3>Evidence-based assumptions</h3><span class="small-label">VERIFY BEFORE ACTING</span></div>${r.unsupported.length?r.unsupported.map(u=>`<div class="assumption-item"><strong>⚠ ${esc(u.role)}</strong><p>${esc(u.message)}</p>${u.source_ids.map(id=>{const x=p.sources.find(s=>s.id===id);return x?`<button data-source="${id}">Read ${esc(x.filename)} ↗</button> `:''}).join('')}</div>`).join(''):`<div class="empty-panel" style="padding:26px 8px"><span class="empty-emoji">✧</span><p>${r.responses_count?'No submitted action differs from its evidence-based working assumption.':'Submit responses to compare them against the evidence-backed release posture.'}</p></div>`}<p class="minor-copy">${esc(r.caveat)}</p></article></div>`;}
function sources(p){return `${titleBlock('STEP 01 · CONTEXT INGESTION','Keep the evidence connected.','Bring relevant communication and project artifacts together. launcheck can cite the exact source behind each rehearsal scenario.',`<button class="btn btn-outline" data-tab="scenarios">Continue to rehearsal →</button>`)}<div class="button-row" style="margin-bottom:18px"><button class="btn" data-action="sync-context">⟳ Search connected sources now</button><button class="btn btn-outline" data-tab="integrations">Manage integrations</button></div><div class="sources-columns"><section class="card card-pad"><div class="compact-head"><h3>Project evidence</h3><span class="badge badge-purple">${p.sources.length} sources</span></div><div class="divider"></div>${p.sources.length?p.sources.map(s=>`<article class="source-full"><div class="source-header"><span class="file-icon ${typeClass(s.kind)}">${iconForSource(s.kind)}</span><div style="min-width:0;flex:1"><div class="source-name">${esc(s.filename)}</div><div class="source-time">${esc(s.kind)} · Imported evidence</div></div><button class="btn btn-outline btn-small" data-source="${s.id}">Inspect ↗</button></div><p class="source-preview">${esc(short(s.content,340))}</p></article>`).join(''):'<div class="empty-panel"><h3>No documents yet</h3><p>Import documents or sample communication to enable source-grounded scenario generation.</p></div>'}</section><aside><div class="card card-pad"><div class="upload-box"><div class="upload-symbol">⇧</div><h3>Add project context</h3><p>Files supplement context imported from authorized accounts. Connected Slack and Gmail searches run automatically when a check is created.</p><form id="uploadForm" class="upload-form"><input type="file" name="files" id="sourceFiles" multiple accept=".pdf,.docx,.txt,.md,.csv,.json,.eml" required/><button class="btn btn-small" type="submit">Upload selected files ↗</button></form><p style="margin-top:12px">PDF, DOCX, TXT, MD, CSV, JSON, EML · 3 MB each</p></div></div></aside></div>`;}
function renderModal(content){
  const root = $('#modalRoot');
  if (!root) {
    toast('Popup container is missing from the page. Check static/index.html.', true);
    return;
  }
  root.innerHTML = `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="launcheck dialog">${content}</div></div>`;
  root.querySelector('input:not([type="hidden"]), textarea, button, select')?.focus();
}
function closeModal(){$('#modalRoot').innerHTML='';}
function createModal(){renderModal(`<div class="eyebrow">NEW ALIGNMENT CHECK</div><h2>Create a project</h2><p>Start with a concrete decision. launcheck will automatically search the Slack channels and Gmail account you've authorized.</p><form id="createForm"><label for="projectName" class="field-label">Project name</label><input id="projectName" required minlength="3" maxlength="90" class="text-field" placeholder="e.g. Phoenix Payroll Go-Live"/><label for="projectDecision" class="field-label">Decision to stress-test</label><textarea required minlength="10" maxlength="800" id="projectDecision" class="text-field" style="min-height:100px" placeholder="e.g. We're launching our payroll integration next Friday…"></textarea><div class="modal-footer"><button class="btn btn-outline" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">Create & find context →</button></div></form>`);}
function sourceModal(id){const s=state.project.sources.find(x=>x.id===id);if(!s)return;renderModal(`<div class="eyebrow">SOURCE EVIDENCE</div><h2>${esc(s.filename)}</h2><p>${esc(s.kind)} · Imported source. Highlighted evidence should always be verified against the original document.</p><div class="source-subheading">EXTRACTED CONTENT</div><div class="source-detail">${esc(s.content)}</div><div class="modal-footer"><button data-action="close-modal" class="btn btn-outline">Close</button></div>`);}
async function act(name, el){try{const p=state.project;
switch(name){
 case 'add-manual-question':addManualQuestionModal();break;
 case 'publish-drafts':{const ids=p.scenarios.filter(q=>q.status==='draft').map(q=>q.id);if(!ids.length)return;if(!confirm('Publish '+ids.length+' questions to employees in the selected departments?'))return;updateProject(await post('/api/projects/'+p.id+'/questions/publish',{ids}));toast('Published '+ids.length+' questions. Employees can refresh their dashboards.');break;}
 case 'publish-one':{if(!confirm('Publish this question to '+(p.scenarios.find(q=>q.id===el.dataset.id)?.role||'the team')+'?'))return;updateProject(await post('/api/projects/'+p.id+'/questions/publish',{ids:[el.dataset.id]}));toast('Question published.');break;}
 case 'delete-draft':{if(!confirm('Delete this unpublished draft?'))return;updateProject(await api('/api/projects/'+p.id+'/questions/'+encodeURIComponent(el.dataset.id),{method:'DELETE'}));toast('Draft deleted.');break;}
 case 'scroll-builder':document.querySelector('.question-builder')?.scrollIntoView({behavior:'smooth'});break;
 case 'open-create':createModal();break;
 case 'create-demo':{const example=await post('/api/demo/create');state.projects.unshift({id:example.id,name:example.name,decision:example.decision,is_demo:1});state.tab='overview';updateProject(example);toast('Fictional judging demo created.');break;}
 case 'connect':window.location.href='/api/connectors/'+el.dataset.provider+'/start';break;
 case 'disconnect':{const provider=el.dataset.provider;if(!confirm('Disconnect '+provider+' and delete its previously imported project context?'))return;await post('/api/connectors/'+provider+'/disconnect');await loadWorkspace();if(state.project)state.project=await api('/api/projects/'+state.project.id);state.channels=[];render();toast(provider+' disconnected; imported content deleted.');break;}
 case 'refresh-channels':await loadChannels();render();toast('Slack channels refreshed.');break;
 case 'slack-people':{state.slackDirectory=await api('/api/team/slack-directory');state.invitationLinks=[];render();toast('Slack directory loaded. Select teammates to create manual invitation links.');break;}
 case 'copy-slack-link':{const item=state.invitationLinks[Number(el.dataset.linkIndex)];if(!item)return;await copyText(item.url);toast('Invitation link copied for '+item.email+'. Send it privately.');break;}
 case 'employee-connect':location.href='/api/team/connectors/'+el.dataset.provider+'/start';break;
 case 'employee-disconnect':{if(!confirm('Disconnect '+el.dataset.provider+' and remove its imported context from all shared launches?'))return;state.employee=await post('/api/team/connectors/'+el.dataset.provider+'/disconnect');await loadEmployeeChannels();renderEmployee();toast('Disconnected');break;}
 case 'employee-refresh-channels':await loadEmployeeChannels();renderEmployee();toast('Channels refreshed');break;
 case 'employee-share':{const id=el.dataset.projectId;const wasShared=el.dataset.shared==='1';if(!wasShared&&!confirm('Share relevant excerpts from your authorized accounts with the company owner for this launch?'))return;state.employee=await post('/api/team/projects/'+id+'/consent',{shared:!wasShared});renderEmployee();toast(!wasShared?'Opted into this launch. Owner can refresh context.':'Access revoked and previously imported content deleted.');break;}
 case 'employee-logout':await post('/api/team/logout');location.href='/?team=1';break;
 case 'logout':await post('/api/logout');location.reload();break;
 case 'sync-context':{if(!p)return;toast('Searching authorized sources for this decision…');const result=await post('/api/projects/'+p.id+'/sync');updateProject(result.project);const count=result.imported.length;toast(count+' relevant source records imported.'+(result.errors.length?' '+result.errors.join('; '):''),!!result.errors.length);break;}
 case 'close-modal':closeModal();break;
 case 'simulate': updateProject(await post(`/api/projects/${p.id}/demo-responses`));state.tab='readiness';render();toast('Fictional responses loaded. Conflicts detected.');break;
 case 'clear-responses':updateProject(await post(`/api/projects/${p.id}/clear-responses`));state.choices={};toast('Scenario answers cleared.');break;
 case 'reset-demo':updateProject(await post('/api/demo/reset'));state.tab='overview';render();toast('Fresh fictional demo loaded.');break;
 case 'generate':if(!state.meta?.ai_enabled){toast('Set OPENAI_API_KEY and restart the server to generate new scenarios. The seeded demo works without a key.',true);return;}if(!p.sources.length){state.tab='sources';render();toast('Upload at least one source first.',true);return;}if(p.scenarios.length&&!confirm('Generating new scenarios will replace current questions and responses. Continue?'))return;toast('Generating source-grounded scenarios…');updateProject(await post(`/api/projects/${p.id}/generate`));state.tab='scenarios';render();toast('Four role-specific scenarios generated.');break;
 case 'save-response':{const s=p.scenarios.find(x=>x.id===el.dataset.scenario);const action=s.question_type==='text'?'text':(state.choices[s.id]||s.response?.action);if(!action){toast('Choose an action first.',true);return;}const participant=$('#participantName')?.value.trim()||`${s.role} representative`;const rationale=$('#rationale')?.value||'';updateProject(await post(`/api/projects/${p.id}/responses`,{scenario_id:s.id,action,participant,rationale}));toast(`${s.role}'s answer was saved.`);break;}
 case 'copy-message':await copyText(p.report.suggested_message);toast('Clarification draft copied.');break;
 case 'share-role':{const selected=p.scenarios.find(x=>x.id===state.roleId);if(!selected)return;const res=await post('/api/projects/'+p.id+'/invites/'+selected.id);const link=new URL(res.url_path,location.origin).toString();await copyText(link);toast('Private invite link copied for '+selected.role+'. Expires in 72 hours and can be used once.');break;}
 } }catch(e){toast(e.message,true);} }
async function copyText(s){if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(s);else {const t=document.createElement('textarea');t.value=s;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();}}
document.addEventListener('click',async ev=>{const tab=ev.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;if(state.tab==='integrations')await loadChannels();if(state.tab==='team')try{state.members=await api('/api/team/members');}catch(e){toast(e.message,true);}render();window.scrollTo({top:0,behavior:'smooth'});return;}const proj=ev.target.closest('[data-project]');if(proj){try{const p=await api(`/api/projects/${proj.dataset.project}`);state.tab='overview';updateProject(p);}catch(e){toast(e.message,true)}return;}const role=ev.target.closest('[data-roleid]');if(role){state.roleId=role.dataset.roleid;render();return;}const choice=ev.target.closest('[data-choice]');if(choice){const pid=choice.dataset.scenario;const name=$('#participantName')?.value||'';const reason=$('#rationale')?.value||'';state.choices[pid]=choice.dataset.choice;render();if($('#participantName'))$('#participantName').value=name;if($('#rationale'))$('#rationale').value=reason;return;}const source=ev.target.closest('[data-source]');if(source){sourceModal(source.dataset.source);return;}const btn=ev.target.closest('[data-action]');if(btn){if(btn.dataset.action==='close-modal'&&ev.target.closest('.modal')&&ev.target.closest('.modal-backdrop')===ev.target)return;await act(btn.dataset.action,btn);}});
document.addEventListener('change', ev=>{
 if(ev.target.id==='qbMode'){state.builderMode=ev.target.value;render();}
});
document.addEventListener('submit',async ev=>{
if(ev.target.id==='questionBuilderForm'){ev.preventDefault();const form=ev.target;const mode=form.querySelector('#qbMode').value;const departments=[...form.querySelectorAll('[name=qbDepartment]:checked')].map(x=>x.value);const count_per_department=Number(form.querySelector('#qbCount').value)||3;const custom_question=form.querySelector('#qbCustom').value.trim();Object.assign(state,{builderMode:mode,builderCount:count_per_department,builderTeams:departments,builderCustom:custom_question});if(!departments.length){toast('Select at least one department.',true);return;}if(mode!=='manual'&&!state.meta?.ai_enabled){toast('Configure OPENAI_API_KEY, or choose CEO questions only.',true);return;}if(mode!=='manual'&&!state.project.sources.length){toast('Import Slack messages or upload context before generating AI questions.',true);return;}try{toast('Preparing editable question drafts…');updateProject(await post('/api/projects/'+state.project.id+'/question-builder/generate',{mode,departments,count_per_department,custom_question}));toast('Draft questions ready. Review and publish them below.');}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='manualQuestionForm'){ev.preventDefault();try{const payload={role:$('#manualDepartment').value,title:$('#manualTitle').value.trim(),situation:state.project.decision,question:$('#manualText').value.trim(),question_type:'text'};updateProject(await post('/api/projects/'+state.project.id+'/questions',payload));closeModal();toast('Custom question saved as draft.');}catch(e){toast(e.message,true);}return;}
if(ev.target.matches('[data-edit-question]')){ev.preventDefault();const f=ev.target;const id=f.dataset.editQuestion;const old=state.project.scenarios.find(x=>x.id===id);const value=n=>f.querySelector('[name="'+n+'"]')?.value||'';const payload={role:value('role'),title:value('title'),situation:value('situation'),question:value('question'),question_type:old.question_type,source_ids:old.source_ids,reference_action:old.reference_action,options:old.question_type==='text'?[]:['hold','pilot','full'].map(action=>({action,label:value('option-'+action)}))};try{updateProject(await api('/api/projects/'+state.project.id+'/questions/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}));toast('Question draft saved.');}catch(e){toast(e.message,true);}return;}

if(ev.target.matches('[data-employee-scenario]')){ev.preventDefault();const form=ev.target;const sid=form.dataset.employeeScenario;const action=form.querySelector('input[type=radio]:checked')?.value|| (form.querySelector('textarea[name=reason][required]')?'text':'');if(!action){toast('Choose an answer.',true);return;}try{state.employee=await post('/api/team/assignments/'+encodeURIComponent(sid)+'/response',{action,rationale:form.querySelector('[name=reason]')?.value||''});renderEmployee();toast('Your response was sent to the CEO readiness report.');}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='slackInviteForm'){ev.preventDefault();const picks=[...ev.target.querySelectorAll('input[name=slackInviteSelect]:checked')].map(c=>Number(c.value));if(!picks.length){toast('Select at least one person to invite.',true);return;}if(picks.length>10){toast('Create up to 10 links at a time.',true);return;}const recipients=picks.map(i=>({email:state.slackDirectory.members[i].email,role:ev.target.querySelector(`[data-slack-role="${i}"]`).value}));if(!confirm('Generate '+recipients.length+' private invitation link(s)? You will send them yourself.'))return;try{const result=await post('/api/team/slack-links',{recipients});state.invitationLinks=result.invites.map(r=>({...r,url:new URL(r.url_path,location.origin).toString()}));state.slackDirectory=await api('/api/team/slack-directory');render();toast(result.invites.length+' invitation link(s) created. No emails sent.');}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='employeeLoginForm'){ev.preventDefault();try{await post('/api/team/login',{email:$('#employeeEmail').value.trim(),password:$('#employeeLoginPassword').value});location.href='/?team=1';}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='employeeJoinForm'){ev.preventDefault();try{await post('/api/team/accept',{token:$('#employeeToken').value,name:$('#employeeName').value.trim(),password:$('#employeePassword').value});location.href='/?team=1';}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='teamInviteForm'){ev.preventDefault();try{const res=await post('/api/team/invite',{email:$('#newEmployeeEmail').value.trim(),role:$('#newEmployeeRole').value.trim()});const url=new URL(res.url_path,location.origin).toString();await copyText(url);toast('Private employee invitation copied! Send it to '+res.email+'.');$('#newEmployeeEmail').value='';$('#newEmployeeRole').value='';}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='employeeChannelsForm'){ev.preventDefault();const ids=[...document.querySelectorAll('input[name=employeeChannel]:checked')].map(x=>x.value);if(ids.length>3){toast('Choose at most 3 channels.',true);return;}try{state.employee=await post('/api/team/connectors/slack/channels',{ids});await loadEmployeeChannels();renderEmployee();toast('Slack channel selection saved.');}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='inviteForm'){ev.preventDefault();const token=$('#inviteToken').value;const action=document.querySelector('input[name=inviteAction]:checked')?.value;if(!action){toast('Choose your response.',true);return;}try{await post('/api/invite/'+encodeURIComponent(token)+'/response',{participant:$('#inviteName').value.trim(),action,rationale:$('#inviteRationale').value});$('#inviteForm').innerHTML='<div class=\"account-tag\">✓ Answer submitted to your project owner. You can close this page.</div>';toast('Response submitted.');}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='setupForm'){ev.preventDefault();const data={company:$('#setupCompany').value.trim(),owner_name:$('#setupName').value.trim(),owner_email:$('#setupEmail').value.trim(),password:$('#setupPassword').value,slack_hint:$('#setupSlack').value.trim(),gmail_hint:$('#setupGmail').value.trim(),wanted:[...document.querySelectorAll('input[name=wanted]:checked')].map(x=>x.value)};try{await post('/api/onboard',data);document.body.classList.remove('onboarding');await loadWorkspace();state.projects=[];state.project=null;state.tab='integrations';render();toast('Company workspace created. Connect the accounts you choose.');}catch(e){toast(e.message,true);}return;}
if(ev.target.id==='loginForm'){ev.preventDefault();try{await post('/api/login',{owner_email:$('#loginEmail').value.trim(),password:$('#loginPassword').value});location.reload();}catch(e){toast(e.message,true)}return;}
if(ev.target.id==='channelsForm'){ev.preventDefault();const ids=[...document.querySelectorAll('input[name=channel]:checked')].map(x=>x.value);if(ids.length>3){toast('Choose up to 3 channels.',true);return;}try{await post('/api/connectors/slack/channels',{ids});state.selectedChannels=ids;toast('Channels saved. New launch checks will search these channels.');render();}catch(e){toast(e.message,true)}return;}
if(ev.target.id==='uploadForm'){ev.preventDefault();const form=ev.target;const data=new FormData(form);if(!data.getAll('files').some(f=>f.size)){toast('Select a file first.',true);return;}try{toast('Extracting uploaded context…');const p=await api(`/api/projects/${state.project.id}/sources`,{method:'POST',body:data});updateProject(p);toast('Project sources imported.');}catch(e){toast(e.message,true);}}if(ev.target.id==='createForm'){ev.preventDefault();const name=$('#projectName').value.trim();const decision=$('#projectDecision').value.trim();try{let p=await post('/api/projects',{name,decision});state.projects.unshift({id:p.id,name:p.name,decision:p.decision});state.tab='sources';state.choices={};closeModal();updateProject(p);toast('Searching your authorized accounts for launch context…');const result=await post('/api/projects/'+p.id+'/sync');updateProject(result.project);toast(result.imported.length+' context sources found.'+(result.errors.length?' '+result.errors.join('; '):'')+(result.checked.length?'':' Connect Slack/Gmail or upload files to continue.'),!!result.errors.length);}catch(e){toast(e.message,true);}}});
init();
})();
